import SwiftUI

enum MemberRole: String, CaseIterable, Identifiable { case athlete = "Athlete", volunteer = "Volunteer", admin = "Admin / Head Coach"; var id: String { rawValue }; var icon: String { switch self { case .athlete: "figure.run"; case .volunteer: "heart.fill"; case .admin: "person.badge.key.fill" } } }
struct Attendee: Identifiable, Hashable { let id = UUID(); let name: String; let role: MemberRole }
struct Event: Identifiable { let id = UUID(); var title: String; var date: Date; var location: String; var attendees: [Attendee] }
struct CommunityMessage: Identifiable { let id = UUID(); let title: String; let body: String; let date = Date() }

struct ContentView: View {
    let sports = ["Hockey", "Basketball", "Floorball", "Golf", "Bowling"]
    @State private var role: MemberRole?
    @State private var name = ""; @State private var age = ""; @State private var contact = ""; @State private var organization = ""
    @State private var selectedSports: Set<String> = []; @State private var stats = ["Bowling": "126"]; @State private var profileComplete = false; @State private var tab = 0
    @State private var selectedEvent: Event?; @State private var newEvent = false; @State private var newMessage = false; @State private var thankYou = false
    @State private var events = [Event(title: "Community Bowling Night", date: .now.addingTimeInterval(86_400 * 4), location: "Sunset Lanes", attendees: [Attendee(name: "Maya", role: .athlete), Attendee(name: "Jordan", role: .volunteer)]), Event(title: "Basketball Skills Clinic", date: .now.addingTimeInterval(86_400 * 10), location: "Northside Gym", attendees: [Attendee(name: "Kai", role: .athlete)])]
    @State private var messages = [CommunityMessage(title: "Welcome to the fall season!", body: "We’re excited to see everyone at our first practice. Bring your energy and a water bottle.")]
    var body: some View { Group { profileComplete ? AnyView(appTabs) : AnyView(onboarding) }.frame(maxWidth: .infinity, maxHeight: .infinity).tint(.blue).fullScreenCover(item: $selectedEvent) { EventDetail(event: $0, currentName: name, currentRole: role ?? .athlete, onResponse: respond) }.fullScreenCover(isPresented: $newEvent) { NewEventView { events.append($0) } }.fullScreenCover(isPresented: $newMessage) { NewMessageView { messages.insert($0, at: 0) } }.fullScreenCover(isPresented: $thankYou) { ThankYouLetter(name: name) } }
    var onboarding: some View { NavigationStack { ScrollView { VStack(alignment: .leading, spacing: 22) { Image(systemName: "medal.fill").font(.system(size: 48)).foregroundStyle(.yellow); Text("Every athlete. Every volunteer. Every moment matters.").font(.title2.bold()); Text("Create your profile to connect with your team and receive updates.").foregroundStyle(.secondary); role == nil ? AnyView(rolePicker) : AnyView(profileForm) }.padding() }.navigationTitle("Welcome") } }
    var rolePicker: some View { VStack(alignment: .leading, spacing: 12) { Text("I am joining as...").font(.headline); ForEach(MemberRole.allCases) { choice in Button { role = choice } label: { HStack { Image(systemName: choice.icon).font(.title2); Text(choice.rawValue).font(.headline); Spacer(); Image(systemName: "chevron.right") }.padding().background(.blue.opacity(0.1), in: RoundedRectangle(cornerRadius: 16)) }.buttonStyle(.plain) } } }
    var profileForm: some View { VStack(alignment: .leading, spacing: 16) { Label("Joining as \(role?.rawValue ?? "")", systemImage: role?.icon ?? "person").font(.headline).foregroundStyle(.blue); TextField("Your name", text: $name).textContentType(.name).textFieldStyle(.roundedBorder); TextField("Your age", text: $age).textFieldStyle(.roundedBorder); TextField("Email or phone number for updates", text: $contact).textContentType(.emailAddress).textFieldStyle(.roundedBorder); if role == .volunteer { TextField("Company or school (optional)", text: $organization).textFieldStyle(.roundedBorder) }; if role == .athlete { Text("Select all sports that apply").font(.headline); SportChips(sports: sports, selection: $selectedSports) }; Button("Create profile") { profileComplete = true }.buttonStyle(.borderedProminent).disabled(name.trimmingCharacters(in: .whitespaces).isEmpty || age.isEmpty || contact.isEmpty); Button("Choose a different role") { role = nil }.font(.footnote) } }
    var appTabs: some View { TabView(selection: $tab) { NavigationStack { eventsPage }.tabItem { Label("Events", systemImage: "calendar.badge.clock") }.tag(0); NavigationStack { calendarPage }.tabItem { Label("Calendar", systemImage: "calendar") }.tag(1); NavigationStack { communityPage }.tabItem { Label("Community", systemImage: "megaphone.fill") }.tag(2); NavigationStack { profilePage }.tabItem { Label("Profile", systemImage: "person.crop.circle") }.tag(3) } }
    var header: some View { HStack(spacing: 12) { Image(systemName: role?.icon ?? "person").font(.title2).foregroundStyle(.blue); VStack(alignment: .leading) { Text("Hi, \(name)").font(.headline); Text(role?.rawValue ?? "").foregroundStyle(.secondary) } } }
    var eventsPage: some View { List { Section { header }; Section("Upcoming events") { ForEach(events.sorted { $0.date < $1.date }) { event in Button { selectedEvent = event } label: { EventRow(event: event) }.buttonStyle(.plain) } }; if role == .volunteer { Section { Button { thankYou = true } label: { Label("Read your latest thank-you letter", systemImage: "envelope.open.fill") } } } }.navigationTitle("Special Olympics").toolbar { if role == .admin { ToolbarItem(placement: .automatic) { Button { newEvent = true } label: { Label("Post event", systemImage: "plus") } } } } }
    var calendarPage: some View { ScrollView { VStack(alignment: .leading, spacing: 20) { Text("Upcoming calendar").font(.title2.bold()).padding(.horizontal); EventCalendar(events: events) { selectedEvent = $0 }.padding(.horizontal); VStack(alignment: .leading, spacing: 10) { Text("All upcoming events").font(.headline); ForEach(events.sorted { $0.date < $1.date }) { event in Button { selectedEvent = event } label: { EventRow(event: event) }.buttonStyle(.plain) } }.padding() } }.navigationTitle("Calendar") }
    var communityPage: some View { List { Section("Team updates") { ForEach(messages) { message in VStack(alignment: .leading, spacing: 6) { Text(message.title).font(.headline); Text(message.body); Text(message.date, style: .date).font(.caption).foregroundStyle(.secondary) }.padding(.vertical, 4) } } }.navigationTitle("Community").toolbar { if role == .admin { ToolbarItem(placement: .automatic) { Button { newMessage = true } label: { Label("Post update", systemImage: "square.and.pencil") } } } } }
    var profilePage: some View { List { Section("Your profile") { header; Text("Updates: \(contact)") }; if role == .athlete { Section("Your sports") { SportChips(sports: sports, selection: $selectedSports) }; Section("Edit your game stats") { ForEach(selectedSports.sorted(), id: \.self) { sport in TextField(statLabel(for: sport), text: Binding(get: { stats[sport, default: ""] }, set: { stats[sport] = $0 })).textFieldStyle(.roundedBorder) }; if selectedSports.isEmpty { Text("Choose sports above to add stats.").foregroundStyle(.secondary) } }; Section("Improvement") { ProgressChart(stats: stats, sports: selectedSports.sorted()); Text("Attendance streak: \(athleteStreak) events").font(.headline); Text("Keep attending to grow your streak!").font(.caption).foregroundStyle(.secondary) }; Section("Badges earned") { BadgeRow(streak: athleteStreak, hasStats: !stats.isEmpty) } }; if role == .volunteer { Section { Button { thankYou = true } label: { Label("Your thank-you letter", systemImage: "heart.text.square.fill") } } } }.navigationTitle("Profile").toolbar { ToolbarItem(placement: .automatic) { Button("Sign out") { reset() } } } }
    var athleteStreak: Int { events.filter { $0.attendees.contains(Attendee(name: name, role: .athlete)) }.count }
    func respond(to event: Event, isComing: Bool) { guard let i = events.firstIndex(where: { $0.id == event.id }) else { return }; let member = Attendee(name: name, role: role ?? .athlete); events[i].attendees.removeAll { $0.name == member.name && $0.role == member.role }; if isComing { events[i].attendees.append(member) }; selectedEvent = events[i]; if isComing && role == .volunteer { thankYou = true } }
    func reset() { role = nil; name = ""; age = ""; contact = ""; organization = ""; selectedSports = []; stats = [:]; profileComplete = false; tab = 0 }
    func statLabel(for sport: String) -> String { switch sport { case "Bowling": "Best bowling score"; case "Golf": "Best golf round"; case "Basketball": "Baskets made"; default: "Goals scored" } }
}

struct SportChips: View { let sports: [String]; @Binding var selection: Set<String>; var body: some View { LazyVGrid(columns: [GridItem(.adaptive(minimum: 125), spacing: 8)], spacing: 8) { ForEach(sports, id: \.self) { sport in Button { if selection.contains(sport) { selection.remove(sport) } else { selection.insert(sport) } } label: { Label(sport, systemImage: selection.contains(sport) ? "checkmark.circle.fill" : "circle").frame(maxWidth: .infinity).padding(.vertical, 9).background(selection.contains(sport) ? .blue : .blue.opacity(0.1), in: Capsule()).foregroundStyle(selection.contains(sport) ? .white : .blue) }.buttonStyle(.plain) } } } }
struct EventRow: View { let event: Event; var body: some View { HStack { Image(systemName: "calendar").foregroundStyle(.blue); VStack(alignment: .leading) { Text(event.title).font(.headline); Text(event.date.formatted(date: .abbreviated, time: .shortened)).font(.subheadline); Text(event.location).font(.caption).foregroundStyle(.secondary) }; Spacer(); Text("\(event.attendees.count)").font(.headline).foregroundStyle(.blue) } } }
struct EventDetail: View { let event: Event; let currentName: String; let currentRole: MemberRole; let onResponse: (Event, Bool) -> Void; @Environment(\.dismiss) private var dismiss; var athletes: [Attendee] { event.attendees.filter { $0.role == .athlete } }; var volunteers: [Attendee] { event.attendees.filter { $0.role == .volunteer } }; var body: some View { NavigationStack { List { Section { Text(event.title).font(.title2.bold()); Label(event.date.formatted(date: .long, time: .shortened), systemImage: "calendar"); Label(event.location, systemImage: "mappin.and.ellipse") }; Section("Are you coming?") { Button("Yes, I am coming") { onResponse(event, true) }.buttonStyle(.borderedProminent); Button("No, I can’t make it today") { onResponse(event, false) }.foregroundStyle(.red) }; Section("Attendance") { HStack { StatBadge(count: volunteers.count, label: "Volunteers", icon: "heart.fill"); StatBadge(count: athletes.count, label: "Athletes", icon: "figure.run") }; if currentRole == .admin { AttendeeList(title: "Athletes coming", attendees: athletes, icon: "figure.run"); AttendeeList(title: "Volunteers coming", attendees: volunteers, icon: "heart.fill") } } }.navigationTitle("Event").toolbar { ToolbarItem(placement: .automatic) { Button("Done") { dismiss() } } } } } }
struct AttendeeList: View { let title: String; let attendees: [Attendee]; let icon: String; var body: some View { VStack(alignment: .leading, spacing: 7) { Text(title).font(.headline); if attendees.isEmpty { Text("No responses yet").foregroundStyle(.secondary) } else { ForEach(attendees) { Label($0.name, systemImage: icon) } } } } }
struct StatBadge: View { let count: Int; let label: String; let icon: String; var body: some View { VStack { Image(systemName: icon); Text("\(count)").font(.title.bold()); Text(label).font(.caption) }.frame(maxWidth: .infinity).padding(10).background(.blue.opacity(0.1), in: RoundedRectangle(cornerRadius: 12)) } }
struct EventCalendar: View { let events: [Event]; let onSelect: (Event) -> Void; let columns = Array(repeating: GridItem(.flexible()), count: 7); var days: [Date] { let c = Calendar.current; let start = c.dateInterval(of: .month, for: .now)?.start ?? .now; return (0..<(c.range(of: .day, in: .month, for: .now)?.count ?? 30)).compactMap { c.date(byAdding: .day, value: $0, to: start) } }; var body: some View { LazyVGrid(columns: columns, spacing: 12) { ForEach(["S", "M", "T", "W", "T", "F", "S"].enumerated().map { "\($0.offset)-\($0.element)" }, id: \.self) { Text(String($0.suffix(1))).font(.caption.bold()).foregroundStyle(.secondary) }; ForEach(days, id: \.self) { day in let matching = events.filter { Calendar.current.isDate($0.date, inSameDayAs: day) }; Button { if let event = matching.first { onSelect(event) } } label: { VStack(spacing: 4) { Text("\(Calendar.current.component(.day, from: day))"); Circle().fill(matching.isEmpty ? .clear : .blue).frame(width: 6, height: 6) }.frame(height: 38) }.buttonStyle(.plain).disabled(matching.isEmpty) } } } }
struct ProgressChart: View { let stats: [String: String]; let sports: [String]; var body: some View { VStack(alignment: .leading, spacing: 12) { Text("Game-stat progress").font(.headline); HStack(alignment: .bottom, spacing: 16) { ForEach(sports, id: \.self) { sport in let value = min(Double(stats[sport] ?? "0") ?? 0, 200); VStack { RoundedRectangle(cornerRadius: 5).fill(.blue.gradient).frame(width: 36, height: max(12, value * 0.55)); Text(sport.prefix(4)).font(.caption2); Text("\(Int(value))").font(.caption2.bold()) } } }.frame(maxWidth: .infinity, minHeight: 140, alignment: .bottom) } } }
struct BadgeRow: View { let streak: Int; let hasStats: Bool; var body: some View { HStack(spacing: 18) { if hasStats { Badge(icon: "chart.line.uptrend.xyaxis", name: "Growing") }; if streak > 0 { Badge(icon: "flame.fill", name: "Streak") }; Badge(icon: "star.fill", name: "Team player") } } }
struct Badge: View { let icon: String; let name: String; var body: some View { VStack { Image(systemName: icon).font(.title2).foregroundStyle(.yellow); Text(name).font(.caption) }.frame(maxWidth: .infinity).padding(8).background(.yellow.opacity(0.12), in: RoundedRectangle(cornerRadius: 12)) } }
struct NewEventView: View { @Environment(\.dismiss) private var dismiss; @State private var title = ""; @State private var location = ""; @State private var date = Date(); let onCreate: (Event) -> Void; var body: some View { NavigationStack { Form { TextField("Event title", text: $title); DatePicker("Date & time", selection: $date); TextField("Location", text: $location) }.navigationTitle("Post an event").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Post") { onCreate(Event(title: title, date: date, location: location, attendees: [])); dismiss() }.disabled(title.isEmpty || location.isEmpty) } } } } }
struct NewMessageView: View { @Environment(\.dismiss) private var dismiss; @State private var title = ""; @State private var bodyText = ""; let onCreate: (CommunityMessage) -> Void; var body: some View { NavigationStack { Form { TextField("Update title", text: $title); TextEditor(text: $bodyText).frame(minHeight: 130) }.navigationTitle("Community update").toolbar { ToolbarItem(placement: .cancellationAction) { Button("Cancel") { dismiss() } }; ToolbarItem(placement: .confirmationAction) { Button("Post") { onCreate(CommunityMessage(title: title, body: bodyText)); dismiss() }.disabled(title.isEmpty || bodyText.isEmpty) } } } } }
struct ThankYouLetter: View { @Environment(\.dismiss) private var dismiss; let name: String; var body: some View { NavigationStack { VStack(alignment: .leading, spacing: 20) { Image(systemName: "heart.fill").font(.largeTitle).foregroundStyle(.pink); Text("Dear \(name),").font(.title2).italic(); Text("Thank you for your help and commitment at practice. Your time, kindness, and encouragement make every athlete feel welcome and supported. We are so grateful to have you on our team!").font(.title3).italic(); Spacer(); Text("With gratitude,\nSpecial Olympics").italic() }.padding(28).navigationTitle("A note for you").toolbar { ToolbarItem(placement: .automatic) { Button("Done") { dismiss() } } } } } }
struct ContentView_Previews: PreviewProvider { static var previews: some View { ContentView() } }
